import{_ as n,C as e,o as i,c as s,E as a,a2 as l}from"./chunks/framework.uPk2SrVb.js";const f=JSON.parse('{"title":"审批已经用掉，外部效果却未必交付","description":"","frontmatter":{"title":"审批已经用掉，外部效果却未必交付","date":"2026-10-31","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"单次审批已消费，能否说明外部效果已交付？（Can evidence that a single-use approval was consumed establish completion of its external effect?）","summary":"来源代码派生的隔离数据库探针每轮只放行一个审批消费者；故意省略后续效果后，重试仍被拒绝。这支持单次消费边界，不能证明外部交付或崩溃恢复。","sources":["https://arxiv.org/html/2610.21063v1","https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84","https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md"],"pageClass":"runtime-v6-article","item_id":"SIG-20261031-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-31-sig-20261031-001-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-10-31-sig-20261031-001.md","filePath":"zh/industry/2026-10-31-sig-20261031-001.md","lastUpdated":null}'),p={name:"zh/industry/2026-10-31-sig-20261031-001.md"};function d(c,t,h,b,u,g){const r=e("ArticleCover"),o=e("ArticleTableScroll");return i(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-10-31-sig-20261031-001-final-cover.png",kicker:"研究成果",title:"审批已经用掉，外部效果却未必交付",summary:"来源代码派生的隔离数据库探针每轮只放行一个审批消费者；故意省略后续效果后，重试仍被拒绝。这支持单次消费边界，不能证明外部交付或崩溃恢复。",version:"2026-10-31",languageHref:"/en/industry/2026-10-31-sig-20261031-001",languageLabel:"English"}),a(o,{language:"zh"}),t[0]||(t[0]=l('<h1 id="审批已经用掉-外部效果却未必交付" tabindex="-1">审批已经用掉，外部效果却未必交付 <a class="header-anchor" href="#审批已经用掉-外部效果却未必交付" aria-label="Permalink to &quot;审批已经用掉，外部效果却未必交付&quot;">​</a></h1><h2 id="重试被拒绝-回答的是哪一个问题" tabindex="-1">重试被拒绝，回答的是哪一个问题 <a class="header-anchor" href="#重试被拒绝-回答的是哪一个问题" aria-label="Permalink to &quot;重试被拒绝，回答的是哪一个问题&quot;">​</a></h2><p>一次审批只允许消费一次，可以有效限制重复使用；但“这次审批已经用过”并不回答“外部动作是否完成”。本次内部实验中，每一轮并发竞争都只有一个成功消费者。另一个受控场景里，探针在消费提交之后故意不执行效果，随后重试仍被拒绝。两种现象并不矛盾：本地令牌状态与外部交付事实是不同的证据。</p><p>这里的对象是 ASU（智能体操作升级审批系统）固定版本中的数据库消费方法。结论限定为：审批已消费与效果已交付必须分账。实验没有制造真实网关崩溃，也没有证明某个已部署系统丢失了用户操作。<a href="https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84" target="_blank" rel="noreferrer">被检查版本的源代码</a></p><h2 id="隔离探针测到了什么" tabindex="-1">隔离探针测到了什么 <a class="header-anchor" href="#隔离探针测到了什么" aria-label="Permalink to &quot;隔离探针测到了什么&quot;">​</a></h2><p>本次使用来源代码派生的隔离函数探针，提取固定版本的消费与事务方法，在 SQLite（嵌入式关系数据库）中运行。审计写入端由内存记录器替代，时间由固定值注入；因此结果不能覆盖原审计系统的故障行为或真实时钟偏差。</p><p>20 轮竞争中，每轮有 16 个独立数据库连接，共 320 次并发调用。每轮恰有一个消费成功，总计 20 次成功、300 次拒绝。它们是这些线程竞争与连接条件下的内部测量，不是多进程压力测试或普遍并发正确性证明。</p><table tabindex="0"><thead><tr><th>控制条件</th><th>消费结果</th></tr></thead><tbody><tr><td>已批准，当前时刻早于到期时刻</td><td>成功</td></tr><tr><td>当前时刻恰等于到期时刻</td><td>拒绝</td></tr><tr><td>已到期</td><td>拒绝</td></tr><tr><td>待审批</td><td>拒绝</td></tr><tr><td>已拒绝</td><td>拒绝</td></tr><tr><td>记录缺失</td><td>拒绝</td></tr></tbody></table><p>来源：2026-10-31 本次内部来源代码派生探针；<a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/asu/store.py" target="_blank" rel="noreferrer">固定版本数据库实现</a>提供被提取方法。六项控制结果与预期一致。本次没有执行完整网关、验证签名或调用真实外部资源。</p><p>受控中断场景的步骤也需要准确命名：第一次消费成功，消费事务提交，测试工具故意省略外部效果，再次消费返回拒绝。“没有效果”是测试构造，不是从真实事故中观察到的结果。它说明这个消费方法本身不提供外部效果交付证据，而不能单独说明整个产品没有其他恢复机制。</p><h2 id="消费事务和效果执行之间的边界" tabindex="-1">消费事务和效果执行之间的边界 <a class="header-anchor" href="#消费事务和效果执行之间的边界" aria-label="Permalink to &quot;消费事务和效果执行之间的边界&quot;">​</a></h2><p>静态代码观察显示，消费方法在立即写事务中执行带条件的状态更新：只有仍获批准且未到期的记录能转成已消费。网关检查会话、用户以及存储和重交描述符摘要，重新解析原始参数，并可再次核验回执；在调用实际执行路径之前，它先消费审批。<a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/asu/gateway.py" target="_blank" rel="noreferrer">网关实现</a></p><p>数据库事务保护的是该审批记录的竞争更新。外部效果是否持久发生，并没有因此自动纳入同一个本地消费事务。把这两层混为一谈，就会把“至多一次消费”误写成“外部效果恰好交付一次”。本次静态顺序与隔离实验支持区分边界，不能给出真实崩溃后的丢失概率。</p><p>微软智能体治理工具包的架构决策 0030 则把审批绑定到动作摘要、策略与链版本，要求执行时重新核验，并将消费放到启动执行的事务或幂等边界。单个允许票并非执行令牌。这是设计要求，可以用于审视边界；它不证明所有集成都满足要求，也不构成两套系统在同等条件下的安全排名。<a href="https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md" target="_blank" rel="noreferrer">动作绑定审批协议</a></p><h2 id="恢复需要额外的效果证据" tabindex="-1">恢复需要额外的效果证据 <a class="header-anchor" href="#恢复需要额外的效果证据" aria-label="Permalink to &quot;恢复需要额外的效果证据&quot;">​</a></h2><p>对接外部资源的执行系统，可以分别保留审批决议、消费提交、效果尝试和效果回执。这是本文基于实验的架构解释，并非已验证的恢复实现。消费提交之后、效果回执之前发生中断时，恢复者需要知道以什么资源证据确认结果，或在什么边界进行补偿。</p><p>因此不能仅凭已消费标记宣布交付，也不能未经资源幂等核验就建议自动重放。若外部资源另有持久幂等键、查询或对账机制，那些证据可以补上本探针未覆盖的部分；探针没有使用它们，并不说明所有集成都没有它们。</p><p>消费先于效果也有清楚的价值：它阻止同一审批被重复使用。本次结果没有证明这个顺序本身错误，更没有证明把顺序倒过来就普遍更安全。具体集成需要同时解释防重放和交付恢复如何成立，不能用其中一个目标的成功替代另一个目标的证据。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>内部实验依据来自本次隔离函数探针，不属于独立第三方检验。源代码观察描述固定提交中的可见执行顺序；公开设计文档提供要求；作者论文的攻击结果仍然是来源报告。这四种角色不能互换。</p><p>代码材料为项目维护者的<a href="https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84" target="_blank" rel="noreferrer">固定版本实现</a>，提交标识为 <code>056742b00a9d116a57525c75704820bb87756e84</code>。对照材料是微软的<a href="https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md" target="_blank" rel="noreferrer">架构决策文档 0030</a>。论文为作者的<a href="https://arxiv.org/html/2610.21063v1" target="_blank" rel="noreferrer">预印本，版本一</a>，本次探针日期为 2026-10-31。论文实验涉及的修订与当前检查提交不同，两个实验还披露了工作目录未提交修改；不能把这些来源当成相同执行版本。</p><p>作者报告，在 609 对任务的精确比较判定器条件下，伪造叙述的攻击成功率从 0.54 降为 0.03。这是论文结果，本次没有复现。论文没有人类受试者实验；其判定器是上界条件，主机确认在所测条件中除授权授予相关差异外与该系统持平。因此不能据此宣称第二设备改善了真实人的决策结果。<a href="https://arxiv.org/html/2610.21063v1" target="_blank" rel="noreferrer">论文第 7 至 8 节</a></p><p>形式化材料明确依赖可信字段决策、封闭注册与诚实渲染来源等假设，也区分密钥签名与人类同意证据。模型部分未覆盖到期、会话绑定、金额聚合、自由文本授予与洪泛控制；红队测试中的历史漏洞注释不是当前失败结果。<a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/formal/README.md" target="_blank" rel="noreferrer">形式化材料</a> 本次未运行这些证明或攻击测试。论文发表、文档引用和实现运行成功都不能自动建立一般有效性。</p><p>封面是依据消费与交付边界创作的编辑图像；空的结果位置表达证据尚未出现，不表示实际系统必然丢失效果。</p><h2 id="仍未测试的交付责任" tabindex="-1">仍未测试的交付责任 <a class="header-anchor" href="#仍未测试的交付责任" aria-label="Permalink to &quot;仍未测试的交付责任&quot;">​</a></h2><p>本次没有测试真实网关崩溃、审计回滚、数据库损坏、多进程调度或外部资源幂等。签名、可信渲染和跨语言规范化是另外的验证问题，不能从本次并发结果推导答案。论文中的静态或推导单元格、占位刺激以及未审计的专有系统，也限制了跨系统推广。</p><p>真正未解决的问题是：在“审批已消费、效果回执缺失”的状态下，这个具体集成能拿出什么可恢复的资源证据？在看到那份证据之前，消费成功可以被准确报告，交付完成则应保留为另一项待判定事实。</p>',27))])}const _=n(p,[["render",d]]);export{f as __pageData,_ as default};
